import { createBucket } from "@tigrisdata/storage";

async function run() {
  while(true) {
    const result = await createBucket("seed-corpus", { enableSnapshot: true });
    if (!result.error) {
      console.log("Bucket created successfully!");
      break;
    }
    console.log("Failed, retrying in 2 seconds...", result.error.message);
    await new Promise(r => setTimeout(r, 2000));
  }
}
run();
